// decodeUnicodeEscape parses the \uXXXX escape beginning at raw[pos] (raw[pos]
// is the backslash) and returns the 16-bit code unit it denotes and the number
// of bytes consumed (6 for a normal \uXXXX). It neither validates nor pairs
// surrogates: the caller decides whether a high surrogate is followed by a
// low one and rejects an orphaned half.
func decodeUnicodeEscape(raw []byte, pos int) (rune, int, error) {
	if pos+5 >= len(raw) || raw[pos] != '\\' || raw[pos+1] != 'u' {
		return 0, 0, keyEncodingError(raw, "incomplete Unicode escape")
	}
	v, ok := parseHex4(raw[pos+2 : pos+6])
	if !ok {
		return 0, 0, keyEncodingError(raw, "malformed Unicode escape")
	}
	return rune(v), 6, nil
}

